  "prediction_basis_card_ids": ["C04","C10","C14","C07","C11","C08","C02","C57","C61","C53"],
  "claims": [
    {
      "claim": "L6 hepatic clearance records show substantial morphine clearance in isolated perfused rat liver (C67, C68, C75, about 26 mL/min) and measurable human liver microsomal glucuronidation intrinsic clearance (C72, C73), providing mechanistic evidence of first-pass metabolism for the morphine scaffold.",
      "card_ids": ["C67","C68","C75","C72","C73"]
    },
    {
      "claim": "No L6 record reports an F below 20% for any opioid; these are rat or in vitro assays for morphine or dimemorfan, not direct human F outcomes for the query.",
      "card_ids": ["C67","C68","C69","C70","C71","C72","C73","C74","C75","C76","C77","C78"]
    },
    {
      "claim": "Visible opioid systemic-F records remain above 20%: codeine 80.5% (C04), pethidine 0.80 (C10, C14), pentazocine 0.68 to 0.70 (C07, C11), meptazinol 27.9% (C08), and naloxegol simulated F 0.90 (C02).",
      "card_ids": ["C04","C10","C14","C07","C11","C08","C02"]
    },
    {
      "claim": "Morphine absorption records remain supportive: rapid small-intestinal absorption in rats (C57) and Caco-2 transport above mannitol and PEG4000 with literature F of 80% (C61).",
      "card_ids": ["C57","C61"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C67","C68","C69","C70","C71","C72","C73","C74","C75","C76","C77","C78"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the visible set.",
    "L6 hepatic clearance data are for morphine or dimemorfan in rat or in vitro systems, not the query; species and analogue transfer are uncertain.",
    "Several opioid F records are cirrhosis-conditioned, and cirrhosis increases F by reducing first-pass metabolism, so healthy-subject transfer is uncertain.",
    "Codeine relative bioavailability (C17, C30) is versus intramuscular dosing, not intravenous, so it is not a pure absolute F value.",
    "Naloxegol F 0.90 is a PBPK simulation (C02), not a measured clinical absolute F for the query scaffold.",
    "No dose-, formulation-, or prandial-state-matched hydromorphone data are available."
  ],
  "decision_summary": "L6 hepatic clearance records provide mechanistic evidence of first-pass metabolism for the morphine scaffold but are rat or in vitro assays for close analogues, not direct F outcomes for the query. No affirmative evidence supports F below 20%, and visible opioid F values remain above 20%. The high prediction is kept with high confidence."
}

